import { RULES, makeQuestion, applyScore, phaseAt } from './core.mjs';
import { townHTML } from './town.mjs';
const app=document.getElementById('app'),help=document.getElementById('help');
const DAYS=['월','화','수','목','금','토','일'];
const GAMES={day:{name:'약속 요일 정하기',short:'요일',icon:'📅',description:'세 사람이 모두 원하는<br>하나의 요일을 찾아요.'},place:{name:'약속 장소 정하기',short:'장소',icon:'🏘️',description:'초록색 장소를 기억하고<br>함께 만날 곳을 찾아요.'},bus:{name:'버스 기억하기',short:'버스',icon:'🚌',description:'세 사람의 버스를 기억하고<br>아무도 타지 않는 번호를 찾아요.'}};
let config={game:'day',difficulty:'easy',rounds:6},session=null,raf=0,phaseKey='',countdownUntil=0,roundStarted=0;
function stop(){cancelAnimationFrame(raf);raf=0;}
function label(value,game=config.game){return game==='day'?DAYS[value]+'요일':game==='place'?'장소 '+(value+1):value+'번';}
function seconds(ms){return ms/1000+'초';}
function ruleDescription(){const r=RULES[config.game][config.difficulty];return config.game==='day'?`각자 <strong>요일 ${r.count}개</strong> 제시 · A <strong>${seconds(r.reveal[0])}</strong> / B·C 각각 <strong>${seconds(r.reveal[1])}</strong> · 응답 <strong>${seconds(r.answer)}</strong>`:config.game==='place'?`각자 <strong>장소 ${r.count}개</strong> 표시 · A·B·C 각각 <strong>${seconds(r.reveal[0])}</strong> · 응답 <strong>${seconds(r.answer)}</strong>`:`각자 <strong>버스 2개</strong> 제시 · A·B·C 각각 <strong>${seconds(r.reveal[0])}</strong> · 응답 <strong>${seconds(r.answer)}</strong>`;}
function home(){stop();session=null;help.classList.remove('hidden');app.innerHTML=`<section class="home-head"><div><div class="eyebrow">MEET & REMEMBER</div><h1>잘 기억하면, 만날 수 있어요.</h1><p class="sub">A, B, C의 정보를 차례로 기억해 보세요.<br>제한 시간 안에 세 사람의 약속을 완성하는 기억력 게임.</p></div><div class="head-sketch" aria-hidden="true"><div class="sketch-tile">A<small>REMEMBER</small></div><div class="sketch-tile">B<small>CONNECT</small></div><div class="sketch-tile">C<small>CHOOSE</small></div></div></section><section class="game-grid" aria-label="게임 선택">${Object.entries(GAMES).map(([id,g])=>`<button class="game-card ${config.game===id?'active':''}" data-game="${id}" aria-pressed="${config.game===id}"><span class="check">✓</span><div class="card-art" aria-hidden="true">${id==='day'?'<span class="cal-mini">월</span><span class="cal-mini">수</span><span class="cal-mini">금</span>':id==='place'?'<span class="town-mini">🏘️</span>':'<span class="bus-mini">🚌 🚏</span>'}</div><h3>${g.name}</h3><p>${g.description}</p></button>`).join('')}</section><section class="config"><div><div class="field-label">난이도</div><div class="segments" aria-label="난이도">${['easy','hard'].map((d,i)=>`<button class="segment ${config.difficulty===d?'active':''}" data-difficulty="${d}" aria-pressed="${config.difficulty===d}">${i?'어려움':'쉬움'}<small>${i?'짧은 시간에 집중해서':'천천히 익숙해지기'}</small></button>`).join('')}</div></div><div><div class="field-label">문항 수</div><div class="segments" aria-label="문항 수">${[6,10,20].map(n=>`<button class="segment ${config.rounds===n?'active':''}" data-rounds="${n}" aria-pressed="${config.rounds===n}">${n}문항<small>${n===6?'가볍게 연습':n===10?'기본 연습':'충분히 연습'}</small></button>`).join('')}</div></div></section><div class="rulebox"><span class="ruleicon">◷</span><div>${ruleDescription()}<br>정보를 보여 주는 동안에는 선택할 수 없어요. A → B → C 이후 답을 골라 주세요.</div></div><div class="start-row"><div class="score-rule"><span>시작 <b>0점</b></span><span>정답 <b>+10점</b></span><span>오답·시간 초과 <b>−5점</b></span></div><button class="button primary" id="start">${GAMES[config.game].short} 게임 시작하기 <span>→</span></button></div><p class="muted-note">점수는 0점 아래로 내려가지 않습니다. 게임 중에는 화면을 유지해 주세요.</p>`;
 app.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{config.game=b.dataset.game;home()});app.querySelectorAll('[data-difficulty]').forEach(b=>b.onclick=()=>{config.difficulty=b.dataset.difficulty;home()});app.querySelectorAll('[data-rounds]').forEach(b=>b.onclick=()=>{config.rounds=Number(b.dataset.rounds);home()});document.getElementById('start').onclick=startSession;
}
function startSession(){stop();help.classList.add('hidden');session={...config,score:0,entries:[],q:null,index:0,settled:false,finished:false};nextRound();}
function nextRound(){stop();session.q=makeQuestion(session.game,session.difficulty);session.index++;session.settled=false;phaseKey='';countdownUntil=performance.now()+3000;roundStarted=countdownUntil;tick();}
function frame(p){const s=session,g=GAMES[s.game];app.innerHTML=`<section class="play-wrap"><div class="play-toolbar"><button class="back-button" id="exit">← 게임 종료</button><div class="game-title">${g.icon} ${g.name}</div><div class="score-chip">${s.score}점</div></div><div class="play-head"><span>${g.short} &nbsp;·&nbsp; 문항 <b>${s.index} / ${s.rounds}</b> &nbsp;·&nbsp; ${s.difficulty==='easy'?'쉬움':'어려움'}</span><span class="time-badge" id="time">3</span></div><div class="timer-track"><div class="timer-fill" id="timer-fill"></div></div><div id="stage"></div></section>`;document.getElementById('exit').onclick=()=>finish(false);}
function arenaHTML(p){const q=session.q,game=session.game;
 if(p.phase==='reveal'){
  if(game==='day')return `<div class="day-reveal">${q.sets[p.person].map(v=>`<div class="day-card ${v===5?'sat':v===6?'sun':''}">${DAYS[v]}<small>DAY</small></div>`).join('')}</div>`;
  if(game==='place')return townHTML({highlight:q.sets[p.person]});
  return `<div class="bus-reveal">${q.sets[p.person].map(v=>`<div class="bus-item"><div class="speech">${v}</div><span class="bus-emoji" aria-hidden="true">🚌</span></div>`).join('')}</div>`;
 }
 if(game==='place')return townHTML({interactive:true,answer:p.phase==='feedback'?q.answer:null,selected:p.phase==='feedback'?p.selected:null});
 return `<div class="${game==='day'?'day-choices':'bus-choices'}">${q.choices.map((v,i)=>`<button type="button" class="answer-button ${p.phase==='feedback'&&v===q.answer?'correct':''} ${p.phase==='feedback'&&v===p.selected&&v!==q.answer?'wrong':''}" data-answer="${v}" aria-label="${label(v,game)}" ${p.phase==='feedback'?'disabled':''}>${game==='day'?DAYS[v]:v}<small>${i+1}</small></button>`).join('')}</div>`;
}
function renderPhase(p){frame(p);const stage=document.getElementById('stage');if(p.phase==='countdown'){stage.innerHTML=`<h2 class="stage-title">준비되셨나요?</h2><p class="stage-subtitle">A → B → C 순서대로 보여 드려요.</p><div class="arena"><div class="countdown"><div class="countdown-num" id="countdown-num">3</div><p>정보를 기억한 뒤 정답을 골라 주세요</p></div></div>`;return;}
 const reveal=p.phase==='reveal',feedback=p.phase==='feedback';const question=session.game==='day'?'모두가 원하는 공통 요일은?':session.game==='place'?'공통으로 만날 수 있는 장소는 어디인가요?':'누구도 타지 않는 버스 번호는 무엇인가요?';
 stage.innerHTML=`<h2 class="stage-title">${reveal?['A','B','C'][p.person]:question}</h2><p class="stage-subtitle">${reveal?(session.game==='bus'?'타야 하는 버스 번호 2개를 기억하세요':session.game==='place'?'초록색 테두리의 장소를 기억하세요':'원하는 요일을 기억하세요'):feedback?'정답과 나의 선택을 확인하세요':session.game==='bus'?'A, B, C 중 아무도 말하지 않은 번호를 선택하세요':'A, B, C 세 사람이 모두 원하는 하나를 선택하세요'}</p><div class="arena">${arenaHTML(p)}</div>${feedback?`<div class="feedback-line ${p.outcome==='correct'?'':'bad'}" role="status">${p.outcome==='correct'?'정답이에요!':p.outcome==='timeout'?'시간이 초과됐어요':'아쉬워요, 오답이에요'} &nbsp; ${p.delta>0?'+':''}${p.delta}점</div><p class="feedback-detail">정답: ${label(session.q.answer)}${p.selected!==null?' · 나의 선택: '+label(p.selected):''}</p><div class="feedback-actions"><button class="button primary next-button" id="next">${session.index===session.rounds?'결과 보기':'다음 문항'} →</button></div>`:`<p class="stage-hint">${reveal?'순서대로 기억하세요…':'화면에서 정답을 클릭하세요'+(session.game==='place'?'':' · 숫자 키로도 선택할 수 있어요')}</p><div class="persons" aria-label="정보 제시 순서">${['A','B','C'].map((v,i)=>`<span class="person-dot ${reveal&&i===p.person?'active':''} ${!reveal||i<p.person?'done':''}">${v}${!reveal||i<p.person?' ✓':''}</span>`).join('')}</div>`}`;
 if(!reveal){app.querySelectorAll('[data-answer]').forEach(b=>{if(feedback)b.disabled=true;else b.onclick=()=>answer(Number(b.dataset.answer));});}
 if(feedback)document.getElementById('next').onclick=()=>{if(session.index===session.rounds)finish(true);else nextRound()};
}
function tick(){if(!session||session.settled||session.finished)return;const now=performance.now(),r=RULES[session.game][session.difficulty];const p=now<countdownUntil?{phase:'countdown',remaining:countdownUntil-now,duration:3000}:phaseAt(now-roundStarted,r);
 if(p.phase==='timeout'){settle(null,'timeout');return;}
 const key=p.phase+(p.person??'');if(key!==phaseKey){phaseKey=key;renderPhase(p);}
 const time=document.getElementById('time');time.textContent=(p.remaining/1000).toFixed(1);time.classList.toggle('urgent',p.phase==='answer'&&p.remaining<1500);document.getElementById('timer-fill').style.transform=`scaleX(${Math.max(0,p.remaining/p.duration)})`;if(p.phase==='countdown')document.getElementById('countdown-num').textContent=Math.ceil(p.remaining/1000);raf=requestAnimationFrame(tick);
}
function answer(value){if(!session||session.settled||session.finished)return;const p=phaseAt(performance.now()-roundStarted,RULES[session.game][session.difficulty]);if(p.phase==='timeout'){settle(null,'timeout');return}if(p.phase!=='answer'||performance.now()<countdownUntil)return;settle(value,value===session.q.answer?'correct':'wrong');}
function settle(selected,outcome){if(!session||session.settled||session.finished)return;stop();session.settled=true;const previous=session.score;session.score=applyScore(previous,outcome);const delta=session.score-previous;session.entries.push({question:session.index,correct:session.q.answer,selected,outcome,delta});renderPhase({phase:'feedback',selected,outcome,delta});document.getElementById('time').textContent='종료';document.getElementById('timer-fill').style.transform='scaleX(0)';}
function finish(completed){if(!session)return;stop();session.finished=true;help.classList.remove('hidden');const s=session,correct=s.entries.filter(e=>e.outcome==='correct').length,wrong=s.entries.filter(e=>e.outcome==='wrong').length,timeout=s.entries.filter(e=>e.outcome==='timeout').length;app.innerHTML=`<section class="play-wrap"><button class="back-button" id="choose">← 게임 선택</button><div class="result-header"><div class="result-icon">${GAMES[s.game].icon}</div><div class="eyebrow">${completed?'PRACTICE COMPLETE':'PRACTICE SUMMARY'}</div><h1>${completed?'연습을 마쳤어요!':'여기까지의 연습 결과예요'}</h1><p class="sub">${GAMES[s.game].name} · ${s.difficulty==='easy'?'쉬움':'어려움'} · ${s.entries.length}/${s.rounds}문항 응답</p><div class="result-score">${s.score}<small>점</small></div></div><div class="result-stats"><div class="good"><span>정답</span><b>${correct}</b></div><div><span>오답</span><b>${wrong}</b></div><div><span>시간 초과</span><b>${timeout}</b></div></div><section class="history"><h3>문항별 기록</h3>${s.entries.length?s.entries.map(e=>`<div class="history-row"><span>${e.question}번</span><div><strong>${e.outcome==='correct'?'정답':e.outcome==='wrong'?'오답':'시간 초과'}</strong> · 정답 ${label(e.correct,s.game)}${e.selected!==null?' / 선택 '+label(e.selected,s.game):''}</div><span class="delta ${e.delta>0?'positive':'negative'}">${e.delta>0?'+':''}${e.delta}점</span></div>`).join(''):'<p class="sub">아직 답한 문항이 없습니다.</p>'}</section><div class="result-actions"><button class="button secondary" id="change">게임 선택</button><button class="button primary" id="retry">같은 설정으로 다시 ↻</button></div><p class="muted-note" style="text-align:center">이 기록은 현재 페이지에서만 유지됩니다.</p></section>`;document.getElementById('choose').onclick=home;document.getElementById('change').onclick=home;document.getElementById('retry').onclick=startSession;window.scrollTo(0,0);}
function helpDialog(){const root=document.getElementById('dialog-root');root.innerHTML=`<div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">약속 정하기 게임 안내</h2><p>A, B, C의 정보를 순서대로 기억한 뒤 제한 시간 안에 하나의 정답을 고르세요. 장소는 초록색 테두리로 표시됩니다.</p><table><thead><tr><th>게임</th><th>쉬움 (제시 / 응답)</th><th>어려움 (제시 / 응답)</th></tr></thead><tbody><tr><td>요일</td><td>3개 · 각 3초 / 6초</td><td>4개 · 각 1.5초 / 3초</td></tr><tr><td>장소</td><td>3개 · 각 3초 / 5초</td><td>4개 · 각 1.5초 / 3초</td></tr><tr><td>버스</td><td>2개 · 각 3초 / 5초</td><td>2개 · 각 1.5초 / 3초</td></tr></tbody></table><p>요일·장소는 모두가 공통으로 원하는 하나를, 버스는 누구도 타지 않는 번호를 선택하세요. 버스 보기 6개 중 정답은 하나입니다.</p><p>시작 0점 · 정답 +10점 · 오답 및 시간 초과 −5점<br>점수는 0점 아래로 내려가지 않습니다. 게임 도중 창을 바꾸어도 시간이 계속 흐릅니다.</p><button class="button primary" id="close-help">확인했어요</button></section></div>`;const close=()=>{root.innerHTML='';help.focus()};document.getElementById('close-help').onclick=close;root.firstChild.onclick=e=>{if(e.target===root.firstChild)close()};document.getElementById('close-help').focus();}
help.onclick=helpDialog;document.getElementById('logo').onclick=e=>{e.preventDefault();if(session&&!session.finished)finish(false);else home()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const close=document.getElementById('close-help');if(close)close.click();return}if(e.repeat||!session||session.finished||session.settled||session.game==='place')return;const index=Number(e.key)-1;if(Number.isInteger(index)&&index>=0&&index<session.q.choices.length)answer(session.q.choices[index]);});
home();
